from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.pages import v23R4


class BtsStatus(pages.BtsStatus):

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(BtsStatus, self).__init__(driver, version)
            self._instance_dict.update(
                {"DUs Status": DusStatusPageV25R1(driver, version),
                 "Cells Status": CellsStatusPageV25R1(driver, version),
                 "X2 Links Status": X2LinksStatusStatusPageV25R1(driver, version),
                 "NG Links Status": NGLinksStatusPageV25R1(driver, version)})


class DusStatusPageV25R1(v23R4.DusStatusPageV23R4):

    MENU_ROUTE_LIST = ['marker-check', 'Site Runtime View', 'DUs Status']


class CellsStatusPageV25R1(v23R4.CellsStatusPageV23R4):

    MENU_ROUTE_LIST = ['marker-check', 'Site Runtime View', 'Cells Status']


class X2LinksStatusStatusPageV25R1(pages.X2LinksStatusStatusPage):

    MENU_ROUTE_LIST = ['marker-check', 'Site Runtime View', 'X2 Links Status']

    def __init__(self, driver, version):
        super(X2LinksStatusStatusPageV25R1, self).__init__(driver, version)
        self._view_panel = v23R4.DusStatusPageViewPanelV23R4(driver, version)
        self.__dict__.update(
            {'get_dus_status_info': self._view_panel.get_cell_info})


class NGLinksStatusPageV25R1(v23R4.NGLinksStatusPageV23R4):

    MENU_ROUTE_LIST = ['marker-check', 'Site Runtime View', 'NG Links Status']
